:root {
  color-scheme: dark;
  --background: oklch(0 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.145 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.18 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.985 0 0);
  --primary-foreground: oklch(0.145 0 0);
  --secondary: oklch(0.205 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.205 0 0);
  --muted-foreground: oklch(0.705 0 0);
  --accent: oklch(0.245 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.70 0.19 25);
  --destructive-foreground: oklch(0.145 0 0);
  --border: oklch(0.27 0 0);
  --input: oklch(0.34 0 0);
  --ring: oklch(0.67 0.17 255);
  --chart-1: oklch(0.67 0.17 255);
  --chart-2: oklch(0.75 0.16 165);
  --chart-3: oklch(0.80 0.16 75);
  --chart-4: oklch(0.72 0.17 300);
  --chart-5: oklch(0.73 0.18 20);
  --chart-teal: oklch(0.62 0.11 185);
  --chart-turquoise: oklch(0.78 0.12 180);
  --chart-teal-strong: oklch(0.48 0.09 185);
  --chart-heat-0: oklch(0.21 0 0);
  --chart-heat-1: oklch(0.35 0.09 155);
  --chart-heat-2: oklch(0.47 0.13 155);
  --chart-heat-3: oklch(0.63 0.15 155);
  --chart-heat-4: oklch(0.72 0.17 150);
  --chart-tooltip-background: oklch(0.18 0 0);
  --chart-tooltip-foreground: oklch(0.985 0 0);
  --chart-tooltip-muted: oklch(0.705 0 0);
  --chart-cursor: oklch(1 0 0);
  --chart-cursor-foreground: oklch(0.18 0 0);
  --radius: 0.5rem;
}

.light {
  color-scheme: light;
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.145 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.145 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.48 0 0);
  --accent: oklch(0.95 0 0);
  --accent-foreground: oklch(0.145 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.90 0 0);
  --input: oklch(0.85 0 0);
  --ring: oklch(0.55 0.20 255);
  --chart-1: oklch(0.55 0.20 255);
  --chart-2: oklch(0.52 0.13 165);
  --chart-3: oklch(0.62 0.15 65);
  --chart-4: oklch(0.55 0.20 300);
  --chart-5: oklch(0.59 0.20 20);
  --chart-heat-0: oklch(0.93 0 0);
  --chart-heat-1: oklch(0.87 0.12 155);
  --chart-heat-2: oklch(0.70 0.15 155);
  --chart-heat-3: oklch(0.62 0.14 155);
  --chart-heat-4: oklch(0.48 0.11 155);
  --chart-teal: oklch(0.59 0.10 185);
  --chart-turquoise: oklch(0.72 0.12 180);
  --chart-teal-strong: oklch(0.40 0.08 185);
  --chart-tooltip-background: oklch(1 0 0);
  --chart-tooltip-foreground: oklch(0.145 0 0);
  --chart-tooltip-muted: oklch(0.48 0 0);
  --chart-cursor: oklch(0.145 0 0);
  --chart-cursor-foreground: oklch(0.985 0 0);
}
